def all_max_rects(g, min_area=8):
    out=[]
    R,C=g.shape
    for v in np.unique(g):
        sub=(g==v)
        heights=np.zeros(C,int)
        for r in range(R):
            heights = [heights[c]+1 if sub[r,c] else 0 for c in range(C)]
            stack=[]
            for c in range(C+1):
                h = heights[c] if c<C else 0
                start=c
                while stack and stack[-1][1]>=h:
                    s,hh=stack.pop()
                    area=hh*(c-s)
                    if area>=min_area:
                        out.append((int(v), r-hh+1, r, s, c-1, area))
                    start=s
                stack.append((start,h))
    # dedupe: keep only maximal rects (not strictly inside another same-color rect)
    out=list(set(out))
    out.sort(key=lambda x:-x[5])
    keep=[]
    for t in out:
        v,r1,r2,c1,c2,a=t
        if not any(u[0]==v and u[1]<=r1 and u[2]>=r2 and u[3]<=c1 and u[4]>=c2 and (u[1],u[2],u[3],u[4])!=(r1,r2,c1,c2) for u in keep):
            keep.append(t)
    return keep

