def max_rect_mask(g, mask):
    R,C=g.shape
    ys,xs=np.where(mask); v=g[ys[0],xs[0]]
    sub=((g==v)&mask)
    heights=np.zeros(C,int); best=(0,None)
    for r in range(R):
        heights=[heights[c]+1 if sub[r,c] else 0 for c in range(C)]
        stack=[]
        for c in range(C+1):
            h=heights[c] if c<C else 0; start=c
            while stack and stack[-1][1]>=h:
                s,hh=stack.pop(); area=hh*(c-s)
                if area>best[0]: best=(area,(r-hh+1,r,s,c-1)); 
                start=s
            stack.append((start,h))
    return best

